import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Problemi più comuni","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/n_matematica-finanziaria-ed-attuariale/nb/nbe.md","filePath":"lezioni/n_matematica-finanziaria-ed-attuariale/nb/nbe.md"}`),a={name:`lezioni/n_matematica-finanziaria-ed-attuariale/nb/nbe.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="problemi-piu-comuni" tabindex="-1">Problemi più comuni <a class="header-anchor" href="#problemi-piu-comuni" aria-label="Permalink to “Problemi più comuni”">​</a></h1><p>Da quanto visto nelle pagine precedenti possiamo pensare il capitale come sempre equivalente a sé stesso ad un certo tasso ed al variare del tempo, cosa che mi porta a considerare equivalenti capitali con tempi diversi e che mi permetterà di mettere assieme operazioni finanziarie sia di montante che di sconto, unificando il valore globale di tali operazioni e fornendomi quindi un quadro esatto della situazione finanziaria del soggetto cui tali operazioni sono riferite.</p><hr><blockquote><p>Quindi potremo sempre considerare più operazioni a tempi diversi oppure un&#39;unica applicazione a tempo totale, cosa che ci permetterà in ogni momento di poter controllare la situazione patrimoniale di una società, azienda, eccetera... spostando in quel dato momento tutti i crediti ed i debiti esistenti.</p></blockquote><hr><ul><li><a href="./nbea.html">unificazione di più crediti</a></li><li><a href="./nbeb.html">sostituzione di più pagamenti</a></li><li><a href="./nbec.html">calcolo del tasso medio per più impieghi</a></li></ul><hr>`,7)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};